'use strict';
const ZeroDownloads=(()=>{
  const LIMIT=100*1024*1024;let rows=[],draft='',tasks=new Map();
  async function refresh(){const records=await dbOp('readonly',s=>s.getAll(),'downloads');rows=records.map(({blob,...meta})=>meta).sort((a,b)=>b.date-a.date);if(!$('sheet').hidden&&tab==='downloads')renderSheet()}
  function html(){return `<form id="fileDownloadForm"><input id="fileDownloadURL" class="sheet-input" type="url" aria-label="${t('文件下载链接','File download URL')}" value="${esc(draft)}" placeholder="${t('HTTPS 文件网址','HTTPS file URL')}"><button class="primary" type="submit">${icon('download')}${t('开始下载','Start download')}</button></form><p class="small-note">${t('网页下载需要服务器允许跨域访问，单文件最大 100 MB。保持此页打开；恢复下载需要服务器支持 Range。系统后台下载在原生 iOS 版提供。','Web downloads require CORS, with a 100 MB limit. Keep this page open. Resuming requires server Range support. System background downloads are provided in the native app.')}</p>${rows.length?rows.map(job=>`<div class="download-row"><strong>${esc(job.name)}</strong><span class="item-sub">${(job.received/1024/1024).toFixed(2)} MB ${job.expected?' / '+(job.expected/1024/1024).toFixed(2)+' MB':''} · ${esc(({running:t('下载中','Downloading'),paused:t('已暂停','Paused'),failed:t('失败','Failed'),complete:t('已完成','Complete'),cancelled:t('已取消','Cancelled')})[job.state]||job.state)}</span><progress value="${job.received}" max="${job.expected||Math.max(job.received,1)}"></progress>${job.error?`<p class="small-note">${esc(job.error)}</p>`:''}<div class="download-actions">${job.state==='running'?`<button data-file-action="pause" data-job="${esc(job.id)}">${t('暂停','Pause')}</button><button data-file-action="cancel" data-job="${esc(job.id)}">${t('取消','Cancel')}</button>`:job.state==='complete'?`<button data-file-action="export" data-job="${esc(job.id)}">${t('导出文件','Export file')}</button>`:`<button data-file-action="resume" data-job="${esc(job.id)}">${t('继续 / 重试','Resume / retry')}</button>`}<button data-file-action="delete" data-job="${esc(job.id)}">${t('删除','Delete')}</button></div></div>`).join(''):empty('download',t('下载的文件保存在这里。','Downloaded files stay here.'))}`}
  async function put(job){await dbOp('readwrite',s=>s.put(job),'downloads');await refresh()}
  async function start(url){try{const source=new URL(url);if(source.protocol!=='https:'||source.username||source.password)throw Error(t('请输入 HTTPS 文件网址。','Enter an HTTPS file URL.'));const job={id:crypto.randomUUID(),url:source.href,name:decodeURIComponent(source.pathname.split('/').pop()||'download'),state:'paused',received:0,expected:0,blob:new Blob(),etag:null,date:Date.now()};draft='';await put(job);launch(job.id)}catch(error){toast(error.message)}}
  function launch(id){run(id).catch(error=>toast(error.message))}
  async function run(id){if(tasks.has(id))return;const job=await dbOp('readonly',s=>s.get(id),'downloads');if(!job)return;const controller=new AbortController(),task={controller,action:null};tasks.set(id,task);job.state='running';job.error=null;let chunks=[job.blob||new Blob()],received=job.received||0,lastSave=received;try{await put(job);const headers={};if(received){headers.Range='bytes='+received+'-';if(job.etag)headers['If-Range']=job.etag}const response=await fetch(job.url,{signal:controller.signal,credentials:'omit',headers,cache:'no-store'});const plan=ZeroCore.downloadResponse(response.status,response.headers,received,job.etag);if(plan.reset){chunks=[];received=0;lastSave=0}job.expected=plan.expected;if(job.expected>LIMIT)throw Error(t('文件超过 100 MB 限制。','File exceeds 100 MB.'));job.etag=response.headers.get('etag');job.mime=response.headers.get('content-type')||'application/octet-stream';const reader=response.body?.getReader();if(!reader)throw Error(t('此浏览器不支持流式下载。','Streaming download unavailable.'));while(true){const {done,value}=await reader.read();if(done)break;received+=value.byteLength;if(received>LIMIT){await reader.cancel();throw Error(t('文件超过 100 MB 限制。','File exceeds 100 MB.'))}chunks.push(value);job.received=received;if(received-lastSave>=1024*1024){job.blob=new Blob(chunks,{type:job.mime});chunks=[job.blob];lastSave=received;await put(job)}}if(!received)throw Error(t('下载内容为空。','Empty download.'));if(job.expected&&received!==job.expected)throw Error(t('文件不完整，可以重试。','Incomplete file. Retry available.'));job.received=received;job.blob=new Blob(chunks,{type:job.mime});job.state='complete';tasks.delete(id);await put(job);toast(t('文件已保存到下载资料库。','Saved in Downloads.'))}catch(error){controller.abort();tasks.delete(id);job.received=received;job.blob=new Blob(chunks,{type:job.mime||'application/octet-stream'});job.state=task.action==='cancel'?'cancelled':task.action==='pause'?'paused':'failed';job.error=error.name==='AbortError'?null:error.message;if(task.action==='cancel'){job.blob=new Blob();job.received=0}await put(job)}finally{if(tasks.get(id)===task)tasks.delete(id)}}
  async function action(type,id){try{if(type==='pause'||type==='cancel'){const task=tasks.get(id);if(task){task.action=type;task.controller.abort()}return}if(type==='resume'){launch(id);return}if(type==='delete'){const task=tasks.get(id);if(task){task.action='cancel';task.controller.abort();while(tasks.has(id))await new Promise(resolve=>setTimeout(resolve,25))}await dbOp('readwrite',s=>s.delete(id),'downloads');await refresh();return}if(type==='export'){const job=await dbOp('readonly',s=>s.get(id),'downloads');if(job?.state==='complete')ZeroTools.downloadBlob(job.blob,job.name)}}catch(error){toast(error.message)}}
  async function init(){try{const records=await dbOp('readonly',s=>s.getAll(),'downloads');for(const job of records.filter(j=>j.state==='running')){job.state='paused';job.error=t('上次下载已中断，可尝试继续。','Previous download interrupted. Resume available.');await dbOp('readwrite',s=>s.put(job),'downloads')}await refresh()}catch{}document.addEventListener('submit',e=>{if(e.target.id==='fileDownloadForm'){e.preventDefault();start($('fileDownloadURL').value)}});document.addEventListener('input',e=>{if(e.target.id==='fileDownloadURL')draft=e.target.value});document.addEventListener('click',e=>{const button=e.target.closest('[data-file-action]');if(button)action(button.dataset.fileAction,button.dataset.job)})}
  async function clear(){for(const task of tasks.values()){task.action='cancel';task.controller.abort()}while(tasks.size)await new Promise(resolve=>setTimeout(resolve,25));await dbOp('readwrite',s=>s.clear(),'downloads');rows=[]}
  return {init,html,refresh,start,clear};
})();
